from pathlib import Path
import json,hashlib
OUT=Path('/tmp/nabt-syntax-independent')
def a(p,*args,positive=True): return {'predicate':p,'args':list(args),'positive':positive}
def s(i,t,**kw): return {'op':'add','source_id':i,'text':t,**kw}
def q(t,atom,status): return {'op':'query','text':t,'gold_atom':atom,'gold_status':[status]}
cases=[
 {'id':'s01','stratum':'scope_explicit_copula','events':[s('a','نورا هي متأهبة.',gold_facts=[a('متأهبة','نورا')]),q('هل نورا هي متأهبة؟',a('متأهبة','نورا'),'SUPPORTED')],'interpretation_note':'Explicit feminine copula licensed by the announced profile; exact property label retained.'},
 {'id':'s02','stratum':'scope_declared_bare','events':[s('a','فرد أثير. أثير حاضر.',gold_facts=[a('حاضر','أثير')]),q('هل أثير هو حاضر؟',a('حاضر','أثير'),'SUPPORTED')],'interpretation_note':'Earlier local individual declaration supplies the announced subject cue.'},
 {'id':'s03','stratum':'scope_predicate_conjunction','events':[s('a','فرد هاشم. هاشم منتبه وصبور.',gold_facts=[a('منتبه','هاشم'),a('صبور','هاشم')]),q('هل هاشم هو صبور؟',a('صبور','هاشم'),'SUPPORTED')],'interpretation_note':'Attached waw shares a previously licensed subject.'},
 {'id':'s04','stratum':'scope_clause_conjunction','events':[s('a','فرد حمزة. فرد سمير. حمزة يقظ وسمير حاضر.',gold_facts=[a('يقظ','حمزة'),a('حاضر','سمير')]),q('هل سمير هو حاضر؟',a('حاضر','سمير'),'SUPPORTED'),q('هل حمزة هو حاضر؟',a('حاضر','حمزة'),'UNKNOWN')],'interpretation_note':'Two declared subjects provide explicit evidence for full-clause conjunction rather than shared subject.'},
 {'id':'s05','stratum':'scope_negation','events':[s('a','فرد عمار. ليس عمار علامة.',gold_facts=[a('علامة','عمار',positive=False)]),q('هل عمار هو علامة؟',a('علامة','عمار'),'REFUTED')],'interpretation_note':'Explicit ليس supplies negative support; the written feminine-form predicate is compatible with a male scholar.'},
 {'id':'s06','stratum':'scope_emphasis','events':[s('a','إنّ ربيع هو حاضر.',gold_facts=[a('حاضر','ربيع')]),q('هل ربيع هو حاضر؟',a('حاضر','ربيع'),'SUPPORTED')],'interpretation_note':'Vocalized إنّ marks emphasis; it is not an extra factual witness or certainty upgrade.'},
 {'id':'s07','stratum':'scope_conditional','events':[s('r','إذا ريان هو حاضر فإن ريان هو شاهد.',gold_rules=[{'body':[a('حاضر','ريان')],'head':a('شاهد','ريان')}]),s('a','ريان هو حاضر.',gold_facts=[a('حاضر','ريان')]),q('هل ريان هو شاهد؟',a('شاهد','ريان'),'SUPPORTED')],'interpretation_note':'A complete conditional with explicit copulas uses the announced source-relative implication contract.'},
 {'id':'s08','stratum':'scope_universal','events':[s('r','كل قارئ متفحص.',gold_rules=[{'body':[a('قارئ','?x')],'head':a('متفحص','?x')}]),s('a','يامن هو قارئ.',gold_facts=[a('قارئ','يامن')]),q('هل يامن هو متفحص؟',a('متفحص','يامن'),'SUPPORTED')],'interpretation_note':'Generic كل introduces a one-way inclusion; the person comes from a separate assertion.'},
 {'id':'s09','stratum':'scope_question','events':[s('a','فرد رائف. هل رائف حاضر؟',gold_facts=[],gold_mode='question',gold_query=a('حاضر','رائف'))],'interpretation_note':'A declared subject may license a bare question; the requested property remains unasserted.','forbid_all_assertions':True},
 {'id':'s10','stratum':'scope_ambiguous_particle','events':[s('a','إن سائر هو حاضر.',gold_facts=[],gold_mode='ambiguous',ambiguity='unvocalized_in')],'interpretation_note':'The announced profile preserves alternatives or suspension for unvocalized إن.','forbid_all_assertions':True},
 {'id':'s11','stratum':'scope_pronoun','events':[s('a','فرد داود. فرد جابر. هو صادق.',gold_facts=[],gold_mode='unresolved',ambiguity='unbound_pronoun')],'interpretation_note':'Two individual declarations do not bind an anaphoric pronoun.','forbid_all_assertions':True},
 {'id':'s12','stratum':'scope_revision','events':[s('a','فرد منير. منير علامة.',gold_facts=[a('علامة','منير')]),q('هل منير هو علامة؟',a('علامة','منير'),'SUPPORTED'),{'op':'replace','source_id':'a','text':'فرد منير. ليس منير علامة.'},q('هل منير هو علامة؟',a('علامة','منير'),'REFUTED')],'interpretation_note':'A fully licensed bare assertion is replaced by an explicit negative with the local identity cue retained.'}
]
data={'schema':'nabt.arabic-syntax.scope-supplement.v1','authorship':'Independent evaluator after declared public scope was provided, before reading the new implementation or its tests. Original 40-case corpus remains unchanged.','purpose':'Measure announced bounded-profile competence separately from broad standalone-Arabic coverage.','cases':cases}
raw=(json.dumps(data,ensure_ascii=False,indent=2)+'\n').encode(); (OUT/'scope_episodes.json').write_bytes(raw)
print(json.dumps({'scope_episodes_sha256':hashlib.sha256(raw).hexdigest(),'episodes':len(cases),'query_checkpoints':sum(e['op']=='query' for c in cases for e in c['events'])},indent=2))
